INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_latissimus_dorsi', 'Latissimus Dorsi', 'Lats', 'back', 'Mid & Lower Back', 'Broadest muscle of the back, drives shoulder extension, adduction, and horizontal pulling') ON CONFLICT (id) DO NOTHING;
