INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_trapezius_lower', 'Lower Trapezius', 'Lower Traps', 'back', 'Lower Scapular Depressors', 'Depresses and stabilizes the scapula during vertical and horizontal pulling') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_teres_major', 'Teres Major', 'Upper Lats / Teres', 'back', 'Posterior Shoulder & Upper Lat', 'Assists latissimus dorsi in adduction and internal rotation of the humerus') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_erector_spinae', 'Erector Spinae', 'Lower Back', 'back', 'Spinal Erectors', 'Extends and stabilizes the vertebral column, foundational in deadlifts and squats') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_deltoid_anterior', 'Anterior Deltoid', 'Front Delt', 'shoulders', 'Anterior Shoulder', 'Shoulder flexion and horizontal adduction, primary in overhead and incline pressing') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_deltoid_lateral', 'Lateral Deltoid', 'Side Delt', 'shoulders', 'Lateral Shoulder', 'Primary shoulder abductor creating shoulder width and 3D silhouette') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_deltoid_posterior', 'Posterior Deltoid', 'Rear Delt', 'shoulders', 'Posterior Shoulder', 'Horizontal abduction and external rotation, key for shoulder balance and posture') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_rotator_cuff', 'Rotator Cuff Complex', 'Rotator Cuff', 'shoulders', 'Glenohumeral Stabilizers', 'Supraspinatus, infraspinatus, teres minor, subscapularis dynamic joint stabilization') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_biceps_long_head', 'Biceps Brachii (Long Head)', 'Outer Bicep', 'arms', 'Anterior Upper Arm', 'Forms the outer bicep peak, crosses the glenohumeral joint') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_biceps_short_head', 'Biceps Brachii (Short Head)', 'Inner Bicep', 'arms', 'Anterior Upper Arm', 'Forms the inner bicep thickness and width') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_brachialis', 'Brachialis', 'Brachialis', 'arms', 'Anterior Arm / Under Bicep', 'Strongest pure elbow flexor, pushes bicep upward for arm thickness') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_triceps_long_head', 'Triceps Brachii (Long Head)', 'Triceps Long Head', 'arms', 'Posterior Upper Arm', 'Largest triceps head, crosses the shoulder joint, emphasized in overhead extensions') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_triceps_lateral_head', 'Triceps Brachii (Lateral Head)', 'Triceps Outer Head', 'arms', 'Posterior Upper Arm', 'Forms the outer triceps horseshoe curve, dominant in pushdowns') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_triceps_medial_head', 'Triceps Brachii (Medial Head)', 'Triceps Inner Head', 'arms', 'Posterior Upper Arm', 'Active across all elbow extension angles, primary elbow stabilizer') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_forearms', 'Forearm Flexors & Extensors', 'Forearms & Grip', 'arms', 'Lower Arm & Wrist', 'Wrist flexion, extension, pronation, supination, and grip endurance') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_quadriceps', 'Quadriceps Femoris', 'Quads', 'legs', 'Anterior Thigh', 'Rectus femoris, vastus lateralis, vastus medialis, vastus intermedius knee extension') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_hamstrings', 'Hamstrings Complex', 'Hamstrings', 'legs', 'Posterior Thigh', 'Biceps femoris, semitendinosus, and semimembranosus hip extension and knee flexion') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_calves_gastrocnemius', 'Gastrocnemius', 'Calves (Outer)', 'legs', 'Posterior Lower Leg', 'Biarticular calf muscle with lateral and medial heads, dominant with straight knees') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_calves_soleus', 'Soleus', 'Calves (Deep/Soleus)', 'legs', 'Posterior Lower Leg', 'Deep postural calf muscle active in seated calf raises and ankle stability') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_tibialis_anterior', 'Tibialis Anterior', 'Shins', 'legs', 'Anterior Lower Leg', 'Dorsiflexes and inverts the foot, crucial for knee protection and deceleration') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_gluteus_maximus', 'Gluteus Maximus', 'Glute Max', 'glutes', 'Posterior Pelvis', 'Largest muscle in the human body, primary hip extensor and external rotator') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_gluteus_medius', 'Gluteus Medius', 'Glute Med', 'glutes', 'Lateral Pelvis', 'Primary hip abductor and pelvic stabilizer in single-leg stance') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_gluteus_minimus', 'Gluteus Minimus', 'Glute Min', 'glutes', 'Deep Lateral Pelvis', 'Synergist for hip abduction and internal rotation') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_rectus_abdominis', 'Rectus Abdominis', 'Abs', 'core', 'Anterior Abdominal Wall', 'Flexes the lumbar spine and stabilizes the pelvis against anterior tilt') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_obliques', 'Internal & External Obliques', 'Obliques', 'core', 'Lateral Abdominal Wall', 'Lateral flexion, trunk rotation, and anti-rotational stability') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_transverse_abdominis', 'Transverse Abdominis', 'Deep Core & TVA', 'core', 'Deep Abdominal Core', 'Deepest abdominal muscle providing intra-abdominal pressure and spinal bracing') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_serratus_anterior', 'Serratus Anterior', 'Serratus', 'core', 'Anterolateral Thorax', 'Protracts and upwardly rotates the scapula, protects shoulder rhythm') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_core', 'Core & Abdominal Complex', 'Core Complex', 'core', 'Midsection Core', 'Deep core, spinal erector, and abdominal wall stabilization') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_adductor_magnus', 'Adductor Magnus', 'Adductor Magnus', 'inner_thigh', 'Medial Thigh (Posterior)', 'Largest adductor with extensor head assisting deep hip extension and stabilization') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_adductor_longus', 'Adductor Longus & Brevis', 'Adductors', 'inner_thigh', 'Medial Thigh (Anterior)', 'Thigh adduction and hip flexion stabilization') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.muscles (id, name, common_name, region_id, subregion, description) VALUES ('m_gracilis', 'Gracilis', 'Gracilis', 'inner_thigh', 'Superficial Medial Thigh', 'Crosses hip and knee joints, aids in adduction and knee flexion') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_bench_press', 'Barbell Bench Press', 'The foundational horizontal push compound movement for chest, front deltoids, and triceps.', 'barbell', 'compound', 'intermediate', '["Lie flat on the bench with eyes positioned directly under the barbell.","Grip the bar slightly wider than shoulder-width and retract your shoulder blades into the bench.","Unrack the bar, lower it with control to mid-chest while tucking elbows at roughly 45-75 degrees.","Drive powerfully upward until arms are extended, keeping feet driven into the floor."]'::jsonb, NULL, 'https://www.youtube.com/embed/rT7DgCr-3pg', 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_barbell_bench_press', 'Incline Barbell Bench Press', 'Angled barbell press emphasizing the clavicular head of the pectoralis major and anterior deltoids.', 'barbell', 'compound', 'intermediate', '["Set bench to a 30-degree incline. Grip bar with hands slightly wider than shoulder-width.","Unrack and lower the bar under control toward upper chest near collarbones.","Press upward and slightly backward over shoulders to complete extension."]'::jsonb, NULL, 'https://www.youtube.com/embed/8iPEnn-ltC8', 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_decline_barbell_bench_press', 'Decline Barbell Bench Press', 'Decline press focusing on the lower sternocostal pectoral fibers with reduced shoulder strain.', 'barbell', 'compound', 'intermediate', '["Secure legs in decline bench rollers. Grip bar slightly wider than shoulder-width.","Lower bar to the lower chest / xiphoid process.","Drive upward locked into the decline plane."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_flat_dumbbell_press', 'Flat Dumbbell Press', 'Allows greater range of motion and converging path for chest muscle fibers.', 'dumbbell', 'compound', 'beginner', '["Sit on bench with dumbbells resting on knees, kick back into lying position.","Press dumbbells up with a natural convergence at the peak without clashing weights.","Lower dumbbells slowly until deep stretch is felt in mid-chest."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_dumbbell_press', 'Incline Dumbbell Press', 'Gold standard upper chest builder providing independent limb stabilization and natural arch.', 'dumbbell', 'compound', 'beginner', '["Set incline to 30-45 degrees. Kick dumbbells into position over upper chest.","Lower dumbbells with elbows at roughly 60 degrees from torso.","Press upward in an arc bringing bells together over upper chest."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_decline_dumbbell_press', 'Decline Dumbbell Press', 'Targets the lower pectoralis fibers while allowing natural wrist rotation.', 'dumbbell', 'compound', 'intermediate', '["Secure feet on decline bench, lie back with dumbbells.","Lower weights to sides of lower chest, then press back to full extension."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_flat_dumbbell_fly', 'Flat Dumbbell Fly', 'Isolation chest movement providing continuous loaded stretch on the pectoral fibers.', 'dumbbell', 'isolation', 'intermediate', '["Lie flat with dumbbells extended over chest, palms facing each other.","Lower arms laterally in an arc with a slight elbow bend until a comfortable chest stretch is achieved.","Contract pectorals to bring dumbbells back along the same arc."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_dumbbell_fly', 'Incline Dumbbell Fly', 'Upper pectoral isolation providing stretch and contraction on a 30-degree incline.', 'dumbbell', 'isolation', 'intermediate', '["Set bench to 30 degrees incline. Hold dumbbells overhead with palms facing inward.","Open arms wide with slight elbow bend, feeling stretch across clavicular head.","Squeeze upper chest to return dumbbells to top."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_crossover_high_to_low', 'Cable Crossover (High to Low)', 'Constant-tension cable adduction targeting lower and sternal pectoral fibers.', 'cable', 'isolation', 'beginner', '["Set pulleys above head height. Grasp handles and step forward with one foot.","With slight elbow bend, pull handles downward and together in front of waist.","Squeeze lower chest hard at peak contraction, return under control."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_fly_low_to_high', 'Cable Fly (Low to High)', 'Scooping cable motion aligning with upper pectoral fibers running from collarbone.', 'cable', 'isolation', 'beginner', '["Set pulleys to lowest position. Grasp handles with palms facing upward.","Sweep hands upward and inward meeting at upper chest height.","Pause and contract clavicular pectorals before lowering slowly."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_middle_cable_fly', 'Middle Cable Fly (Chest Level)', 'Horizontal cable fly matching mid-pectoral fibers with peak tension in contraction.', 'cable', 'isolation', 'beginner', '["Set pulleys at chest level. Step forward into slight staggered stance.","Hug arms inward in horizontal plane, squeezing chest tightly at midpoint.","Control the eccentric stretch back to start."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_chest_press', 'Machine Chest Press', 'Guided chest pressing allowing high mechanical tension with minimal balance demands.', 'machine', 'compound', 'beginner', '["Adjust seat so handles align with mid-chest. Plant feet flat.","Press handles forward smoothly until elbows are nearly extended.","Return slowly feeling loaded pectoral stretch."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_machine_chest_press', 'Incline Machine Chest Press', 'Converging incline machine press maximizing upper chest hypertrophy safely.', 'machine', 'compound', 'beginner', '["Adjust seat height so handles sit just below collarbone level.","Press upward along machine track, squeezing upper chest at peak.","Lower weights smoothly to starting depth."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_pec_deck_fly', 'Pec Deck Machine Fly', 'Pure chest isolation with fixed elbow position eliminating triceps involvement.', 'machine', 'isolation', 'beginner', '["Adjust seat so arms are roughly horizontal to floor when gripping pads/handles.","Pull arms together across chest with smooth squeeze.","Allow weights to stretch chest slowly back without losing shoulder positioning."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_push_up', 'Push-Up', 'Bodyweight cornerstone building chest, anterior delts, triceps, and abdominal core.', 'bodyweight', 'compound', 'beginner', '["Place hands slightly wider than shoulder-width, body in a rigid straight line plank.","Lower chest until 1-2 inches off floor with elbows at 45-degree angle.","Push the ground away to full elbow extension, protracting shoulders at top."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_push_up', 'Incline Push-Up (Hands Elevated)', 'Elevated hands regression reducing load while maintaining movement pattern.', 'bodyweight', 'compound', 'beginner', '["Place hands on sturdy bench or box. Keep body straight from head to heels.","Lower chest to edge of bench and push back up smoothly."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_decline_push_up', 'Decline Push-Up (Feet Elevated)', 'Elevated feet variation shifting body mass toward upper pectorals and shoulders.', 'bodyweight', 'compound', 'intermediate', '["Place feet on bench or box, hands on floor beneath shoulders.","Lower chest toward floor maintaining tight core.","Press back up to locked arms."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_weighted_push_up', 'Weighted Push-Up', 'Progressive overload push-up using weight vest or plate on upper back.', 'bodyweight', 'compound', 'advanced', '["Position weight plate on upper back or wear weighted vest.","Perform strict full range push-ups without sagging hips."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_chest_dips', 'Chest Dips (Leaning Forward)', 'Bodyweight or weighted dip with forward torso lean to maximize lower chest recruitment.', 'bodyweight', 'compound', 'intermediate', '["Grip parallel bars, lean torso forward at roughly 30 degrees with knees bent.","Lower body until elbows reach 90 degrees and chest feels a deep loaded stretch.","Press upward through palms focusing on pectoral contraction rather than triceps."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_smith_machine_bench_press', 'Smith Machine Bench Press', 'Fixed bar path pressing allowing complete focus on pectoral muscle fiber recruitment.', 'smith_machine', 'compound', 'beginner', '["Position flat bench so bar touches mid-chest on descent.","Unlock bar, lower smoothly to light chest touch, and press to lockout."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_smith_machine_incline_press', 'Smith Machine Incline Press', 'Incline angle on fixed bar path maximizing clavicular chest tension with safe failure.', 'smith_machine', 'compound', 'beginner', '["Set incline bench at 30 degrees directly under Smith bar.","Lower bar to upper chest and drive upward with constant pectoral tension."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_neutral_grip_dumbbell_press', 'Neutral Grip Dumbbell Press', 'Dumbbell press with palms facing each other to spare shoulders and isolate sternal chest.', 'dumbbell', 'compound', 'beginner', '["Lie flat holding dumbbells with neutral palms-in grip.","Tuck elbows close to ribs on descent, press up while maintaining neutral wrists."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_svend_press', 'Svend Press (Plate Squeeze Press)', 'Standing isometric pectoral squeeze press using weight plates.', 'barbell', 'isolation', 'intermediate', '["Stand tall sandwiching two small bumper or iron plates between your flat palms at chest height.","Squeeze hands together as hard as possible, pressing plates straight forward until arms extend.","Hold peak squeeze for 1-2 seconds, then return to chest."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_floor_press_barbell', 'Barbell Floor Press', 'Partial range pressing off the floor emphasizing triceps lockout and reducing shoulder extension.', 'barbell', 'compound', 'intermediate', '["Lie flat on floor with knees bent and feet flat under a rack.","Unrack barbell and lower until triceps rest gently on floor without bouncing.","Press powerfully upward to lockout."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_floor_press_dumbbell', 'Dumbbell Floor Press', 'Floor press using dumbbells to allow neutral or angled wrist variations.', 'dumbbell', 'compound', 'beginner', '["Lie on floor with dumbbells at chest level. Press up to full extension.","Lower until upper arms touch floor pause briefly, press up."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_landmine_chest_press', 'Landmine Chest Press (Single-Arm)', 'Angular standing press following natural shoulder biomechanics with high upper chest stimulus.', 'barbell', 'compound', 'intermediate', '["Stand facing landmine station, hold end of barbell at shoulder with one hand in staggered stance.","Press barbell forward and upward following the arc, squeezing upper chest at peak.","Lower slowly under control."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_arm_cable_chest_press', 'Single-Arm Cable Chest Press', 'Standing unilateral cable press delivering continuous resistance and anti-rotational core work.', 'cable', 'compound', 'intermediate', '["Set cable at chest height. Take handle in one hand, step into staggered stance.","Press straight forward without letting torso rotate.","Return slowly under cable stretch."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_cable_crossover', 'Seated Cable Crossover', 'Seated variation eliminating momentum and core compensation for pure chest isolation.', 'cable', 'isolation', 'beginner', '["Place upright bench between cable towers. Sit back and grasp handles.","Adduct arms across chest in a smooth arc, pausing at peak squeeze."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hammer_strength_flat_press', 'Hammer Strength Flat Press', 'Plate-loaded converging press mimicking dumbbell path with barbell load capacity.', 'machine', 'compound', 'intermediate', '["Load plates on machine, adjust seat so handles align with lower/mid pectoral line.","Drive handles outward and forward along converging path, squeeze chest hard."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hammer_strength_incline_press', 'Hammer Strength Incline Press', 'Converging plate-loaded machine isolating upper chest without rotator cuff strain.', 'machine', 'compound', 'intermediate', '["Adjust seat so handles are at collarbone level.","Press upward along diverging/converging path, control the descent."]'::jsonb, NULL, NULL, 'chest') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_conventional_deadlift', 'Conventional Barbell Deadlift', 'The king of posterior chain movements engaging the spinal erectors, lats, glutes, and hamstrings.', 'barbell', 'compound', 'advanced', '["Stand with feet hip-width apart, barbell over mid-foot.","Hinge at hips, grip bar just outside knees. Depress lats and brace core.","Drive feet through floor, extending knees and hips simultaneously to lockout."]'::jsonb, NULL, 'https://www.youtube.com/embed/op9kVnSso6Q', 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_sumo_deadlift', 'Sumo Barbell Deadlift', 'Wide stance deadlift variation shifting more demand onto the adductors and quads while working the back.', 'barbell', 'compound', 'advanced', '["Stand with feet wide pointing toward plates. Grip bar inside knees.","Open knees out over toes, keep torso upright, and drive through heels to lockout."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_bent_over_row_overhand', 'Barbell Bent-Over Row (Overhand)', 'Classic horizontal pulling compound exercise targeting the upper back, rhomboids, and lats.', 'barbell', 'compound', 'intermediate', '["Hinge at hips with torso around 45 degrees, back flat. Grip bar with overhand grip.","Pull bar toward lower ribcage / navel by driving elbows back.","Squeeze shoulder blades together at top, lower under control."]'::jsonb, NULL, 'https://www.youtube.com/embed/G8l_8chR5BE', 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_row_underhand', 'Barbell Bent-Over Row (Underhand / Yates)', 'Supinated grip row variation emphasizing lower lat recruitment and greater bicep leverage.', 'barbell', 'compound', 'intermediate', '["Hold barbell with palms facing forward (underhand). Torso at 50-60 degrees.","Pull bar smoothly into lower waist while keeping elbows tucked close to torso."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_pendlay_row', 'Pendlay Row (Strict Dead-Stop)', 'Strict horizontal row starting from a dead stop on the floor each rep, building explosive pulling power.', 'barbell', 'compound', 'advanced', '["Torso parallel to floor with plates resting on ground. Overhand grip slightly wider than shoulder.","Explosively pull bar into sternum without rising with hips.","Return bar completely to floor for dead stop between reps."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_pull_up', 'Pull-Up (Overhand Wide Grip)', 'Benchmark bodyweight vertical pull building wide lat wingspan and upper back density.', 'bodyweight', 'compound', 'intermediate', '["Grip bar with overhand grip wider than shoulders. Hang in full dead hang.","Depress scapulae and pull elbows down and back toward ribs.","Bring chin clearing over bar, pause, and lower to full dead hang."]'::jsonb, NULL, 'https://www.youtube.com/embed/eGo4IYlbE5g', 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_chin_up', 'Chin-Up (Underhand Supinated Grip)', 'Supinated vertical pull maximizing biceps leverage while powerfully working the lats.', 'bodyweight', 'compound', 'intermediate', '["Grip bar shoulder-width with palms facing you (underhand).","Pull chest up toward bar, driving elbows downward.","Lower smoothly to full elbow extension."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_neutral_grip_pull_up', 'Neutral Grip Pull-Up', 'Parallel grip pull-up offering shoulder-friendly biomechanics and strong brachialis recruitment.', 'bodyweight', 'compound', 'intermediate', '["Grasp parallel handles with palms facing each other.","Pull body up leading with chest until chin passes handles.","Lower under complete control."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lat_pulldown_wide', 'Wide-Grip Lat Pulldown', 'Cable machine vertical pull isolating the latissimus dorsi with adjustable resistance.', 'cable', 'compound', 'beginner', '["Sit facing machine with thighs secured under pads. Grasp bar wide with overhand grip.","Lean back slightly (10-15 degrees), pull bar down toward upper chest touching collarbones.","Squeeze lats at bottom, allow bar to return smoothly to full overhead stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lat_pulldown_close_grip', 'Close-Grip Lat Pulldown (V-Bar)', 'Close neutral-grip cable pulldown allowing deep lat stretch and long range of motion.', 'cable', 'compound', 'beginner', '["Attach V-bar handle to pulldown cable. Secure thighs.","Pull handle down to upper chest, keeping elbows tight to body.","Elevate arms slowly to feel extreme lat stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lat_pulldown_reverse_grip', 'Reverse-Grip Lat Pulldown', 'Underhand pulldown variation increasing bicep leverage and targeting lower lats.', 'cable', 'compound', 'beginner', '["Grip straight bar shoulder-width with palms facing you.","Pull down to mid-chest with elbows driving back and down.","Control the ascent to full stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_cable_row', 'Seated Cable Row (V-Bar)', 'Horizontal cable row building mid-back thickness, rhomboids, and lower lats.', 'cable', 'compound', 'beginner', '["Sit on bench with feet on footplates, knees slightly bent. Grasp V-bar handle.","Sit upright with chest proud. Pull handle into navel, driving elbows back.","Squeeze mid-back tightly, then extend arms with slight forward hinge stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_arm_dumbbell_row', 'Single-Arm Dumbbell Row', 'Unilateral free-weight row correcting muscular imbalances and allowing immense stretch.', 'dumbbell', 'compound', 'beginner', '["Place one knee and hand on flat bench, torso parallel to floor.","Hold dumbbell with free hand hanging straight down.","Pull dumbbell in an arc toward hip, driving elbow to ceiling.","Lower under control to a deep lat stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_meadows_row', 'Meadows Row (Landmine)', 'Overhand landmine row developed by John Meadows to blast the upper lats, teres major, and rear delts.', 'barbell', 'compound', 'intermediate', '["Stand perpendicular to end of landmine bar in staggered stance.","Grip the thick collar with an overhand grip.","Row the elbow up and out to side, achieving deep squeeze in upper lat and teres.","Lower slowly to floor stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_kroc_row', 'Kroc Row (Heavy High-Rep Dumbbell Row)', 'Heavy high-rep dumbbell row incorporating controlled body English to build grip and back mass.', 'dumbbell', 'compound', 'advanced', '["Brace with hand on dumbbell rack or bench.","Using a heavy dumbbell, explode elbow toward hip for 15-25 brutal reps with full stretch at bottom."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_t_bar_row_chest_supported', 'Chest-Supported T-Bar Row', 'Eliminates lower back fatigue entirely, allowing pure mid-back and upper lat isolation.', 'machine', 'compound', 'beginner', '["Lie chest-down on angled pad. Grasp handles with preferred width grip.","Pull weight up by driving elbows back, retracting shoulder blades fully.","Lower smoothly without allowing weight to rest between reps."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_t_bar_row_free_weight', 'T-Bar Row (Free-Weight)', 'Classic heavy back builder requiring strong spinal erectors and hamstring stabilization.', 'barbell', 'compound', 'intermediate', '["Straddle landmine bar with V-handle underneath collar.","Hinge hips at 45 degrees, pull handle to lower abdomen, keeping spine neutral.","Lower to complete stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_chest_supported_machine_row', 'Chest-Supported Machine Row', 'Guided horizontal row with chest pad ensuring zero lower back strain.', 'machine', 'compound', 'beginner', '["Adjust chest pad and seat height so handles align with mid-chest.","Pull handles back smoothly, squeezing shoulder blades together.","Control the weight stack back to starting stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_straight_arm_cable_pulldown', 'Straight-Arm Cable Pulldown', 'Pure lat isolation movement eliminating biceps involvement via extended elbows.', 'cable', 'isolation', 'beginner', '["Stand facing high cable with straight or rope attachment. Grasp with arms extended.","Hinge forward slightly at hips. With straight arms, sweep bar down in an arc to thighs.","Contract lats hard at bottom, then return slowly to forehead height."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_pullover', 'Dumbbell Pullover', 'Classic exercise expanding ribcage and providing loaded eccentric stretch to the lats and serratus.', 'dumbbell', 'isolation', 'intermediate', '["Lie perpendicular across bench with upper back supported, hips lowered slightly.","Hold dumbbell with palms flat under top plate over chest.","Lower dumbbell back over head in an arc until deep lat stretch is achieved.","Pull dumbbell back over chest using lats."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_arm_cable_lat_pulldown', 'Single-Arm Kneeling Cable Lat Pulldown', 'Unilateral cable pulldown aligning line of pull directly with individual lat fiber angles.', 'cable', 'compound', 'intermediate', '["Half-kneel facing cable tower with single handle attached high.","Reach up to full stretch, pull elbow down tight to ribcage.","Pause and squeeze lower lat, return slowly."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_inverted_row', 'Inverted Row (Australian Pull-Up)', 'Horizontal bodyweight pull on barbell or rings developing mid-back control and posture.', 'bodyweight', 'compound', 'beginner', '["Set barbell in rack at waist height. Hang underneath with heels on floor.","Maintain rigid straight plank body line. Pull chest up to touch bar.","Lower under control to full arm hang."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_rack_pull', 'Rack Pull (Block Pull)', 'Partial deadlift from knee height overloading the upper back, traps, and spinal erectors.', 'barbell', 'compound', 'intermediate', '["Set bar on safety pins just below or at knee level.","Hinge hips back, brace core, and drive through hips to full upright lockout.","Lower bar to pins under control."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_good_morning_barbell', 'Barbell Good Morning', 'Hip hinge movement placing enormous eccentric overload on spinal erectors and hamstrings.', 'barbell', 'compound', 'advanced', '["Place barbell across upper back as in a squat. Soften knees slightly.","Hinge hips backward keeping spine locked flat until torso is near parallel.","Drive hips forward to return to standing."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hyperextension_back', 'Back Extension (Hyperextension Bench)', 'Focused spinal extension exercise isolating lower back erectors with glute/hamstring assistance.', 'bodyweight', 'isolation', 'beginner', '["Set pad at hip level on 45-degree bench. Cross arms over chest.","Bend forward at waist with neutral spine, then extend back up until body is straight."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_reverse_hyperextension', 'Reverse Hyperextension', 'Decompresses the lumbar spine while strengthening lower back, glutes, and hamstrings.', 'machine', 'compound', 'intermediate', '["Lie face down on machine with legs hanging. Grip handles firmly.","Swing legs up until parallel with torso, squeezing glutes and lower back.","Lower smoothly into spinal decompression."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_snatch_grip_deadlift', 'Snatch-Grip Deadlift', 'Extra-wide grip deadlift creating extended range of motion and exceptional upper trap/lat demand.', 'barbell', 'compound', 'advanced', '["Take a very wide collar-to-collar grip on barbell.","Drop hips lower than conventional deadlift, pull bar smoothly from floor to full hip extension."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seal_row', 'Seal Row (Barbell on Elevated Bench)', 'Bench elevated on blocks allowing dead-hang barbell row with zero lower back strain.', 'barbell', 'compound', 'intermediate', '["Lie face down on horizontal bench elevated on boxes or pins.","Pull barbell straight up to touch underside of bench, driving elbows to ceiling.","Lower to full hang stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_neutral_grip_dumbbell_row', 'Two-Arm Neutral Grip Dumbbell Row (Chest Supported)', 'Angled bench row with dumbbells allowing independent arm path and deep squeeze.', 'dumbbell', 'compound', 'beginner', '["Set incline bench to 30-45 degrees, lie prone with dumbbells in hands.","Pull elbows back along ribcage, squeezing mid-back and lats.","Lower slowly to full stretch."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_shrug', 'Barbell Shrug', 'Heavy overload for the upper trapezius fibers to build thick neck and shoulder yoke.', 'barbell', 'isolation', 'beginner', '["Hold barbell at arm length in front of thighs with shoulder-width grip.","Elevate shoulders straight up toward ears without rolling shoulders.","Hold peak trap contraction for 1 second, lower slowly."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_shrug', 'Dumbbell Shrug', 'Allows arms to hang naturally at sides for optimal line of upper trapezius pull.', 'dumbbell', 'isolation', 'beginner', '["Hold dumbbells at sides with palms facing inward.","Shrug shoulders directly upward toward ears, pause at top, lower under control."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_shrug', 'Cable Shrug', 'Constant tension trap elevation using low pulley with straight or angled bar.', 'cable', 'isolation', 'beginner', '["Attach bar to low pulley. Stand tall and elevate shoulders against continuous cable resistance."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_behind_back_barbell_shrug', 'Behind-the-Back Barbell Shrug', 'Barbell held behind thighs for enhanced middle and upper trapezius fiber recruitment.', 'barbell', 'isolation', 'intermediate', '["Hold barbell behind glutes with overhand grip.","Shrug shoulders upward and slightly backward, pausing at peak contraction."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lat_pulldown_behind_neck', 'Lat Pulldown Behind Neck', 'Classic vertical pull emphasizing lower traps, rhomboids, and teres with strict form.', 'cable', 'compound', 'intermediate', '["Sit facing pulldown machine, pull bar smoothly behind head to base of neck.","Do not thrust neck forward. Lower under control."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_v_bar_lat_pulldown', 'V-Bar Lat Pulldown (Dual Handles)', 'Dual D-handle or V-bar pulldown offering wrist freedom and deep lat activation.', 'cable', 'compound', 'beginner', '["Pull handles down to upper chest, flared elbows rotating slightly inward at bottom squeeze."]'::jsonb, NULL, NULL, 'back') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_overhead_press', 'Barbell Overhead Press (Military Press)', 'The definitive vertical push compound exercise building shoulder mass and full-body stabilization.', 'barbell', 'compound', 'intermediate', '["Stand with feet hip-width apart. Hold barbell across collarbones with hands just outside shoulders.","Squeeze glutes and brace core. Press bar overhead in a vertical line, moving head back slightly to clear chin.","Lock out arms overhead with bar directly over mid-foot. Lower under control."]'::jsonb, NULL, 'https://www.youtube.com/embed/2yjwXTZQDDI', 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_dumbbell_shoulder_press', 'Seated Dumbbell Shoulder Press', 'Seated overhead press isolating deltoids with free range of motion and back support.', 'dumbbell', 'compound', 'beginner', '["Sit on upright bench. Kick dumbbells to shoulder height with palms facing forward or slightly angled.","Press dumbbells upward in an arc meeting overhead without clashing.","Lower weights under control until hands reach ear level."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_standing_dumbbell_shoulder_press', 'Standing Dumbbell Shoulder Press', 'Standing overhead press demanding substantial core bracing and stabilizer recruitment.', 'dumbbell', 'compound', 'intermediate', '["Stand tall with dumbbells at shoulders, press vertically overhead while bracing glutes and abs."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_arnold_press', 'Arnold Press', 'Rotating dumbbell press hitting all three deltoid heads through an extended range of motion.', 'dumbbell', 'compound', 'intermediate', '["Sit upright holding dumbbells in front of shoulders with palms facing you (as at top of curl).","As you press upward, rotate wrists so palms face forward at top of movement.","Reverse rotation smoothly on the way down."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_behind_neck_press', 'Behind-the-Neck Barbell Press', 'Advanced shoulder press emphasizing lateral deltoids and upper back.', 'barbell', 'compound', 'advanced', '["Grip barbell wide. Lower carefully to base of neck with upright posture, press to lockout."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_push_press_barbell', 'Barbell Push Press', 'Dynamic overhead press using leg drive to propel heavy loads overhead.', 'barbell', 'compound', 'advanced', '["Dip knees 2-3 inches with vertical torso, then explosively drive legs and press bar overhead."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_shoulder_press', 'Machine Shoulder Press', 'Guided overhead press maximizing deltoid overload without balance restrictions.', 'machine', 'compound', 'beginner', '["Adjust seat so handles start at ear height. Press handles upward to near-lockout."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_smith_machine_overhead_press', 'Smith Machine Overhead Press', 'Strict vertical pressing along guided track allowing safe training to failure.', 'smith_machine', 'compound', 'beginner', '["Set bench under bar. Unhook bar, lower to chin height, press upward smoothly."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_lateral_raise', 'Dumbbell Lateral Raise', 'The cornerstone isolation exercise for lateral deltoid width and shoulder capping.', 'dumbbell', 'isolation', 'beginner', '["Stand with dumbbells at sides, slight forward torso lean (10-15 degrees).","Raise arms out to sides leading with elbows until parallel to floor.","Pour water forward slightly at top, pause, and lower slowly without swinging."]'::jsonb, NULL, 'https://www.youtube.com/embed/3VcKaXpzqRo', 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_lateral_raise', 'Cable Lateral Raise', 'Continuous resistance lateral raise providing peak tension at the bottom of the movement.', 'cable', 'isolation', 'beginner', '["Set low pulley. Stand with cable passing behind or in front of body.","Raise handle out to shoulder height with slight elbow bend. Control the descent."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_leaning_cable_lateral_raise', 'Leaning Cable Lateral Raise', 'Leaning away from cable pillar to overload the stretched position of the lateral deltoid.', 'cable', 'isolation', 'intermediate', '["Hold cable pole with inside hand and lean torso outward at a 30-degree angle.","Raise cable handle out to side, achieving deep contraction with zero momentum."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_lateral_raise', 'Machine Lateral Raise', 'Padded elbow lever machine completely removing forearm and grip fatigue from side delts.', 'machine', 'isolation', 'beginner', '["Sit with pads against outer elbows. Drive elbows outward and upward to shoulder height.","Hold peak squeeze for 1 second, lower slowly."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_behind_back_cable_lateral_raise', 'Behind-the-Back Cable Lateral Raise', 'Cable routed behind the back to initiate pull directly in the scapular plane.', 'cable', 'isolation', 'intermediate', '["Attach D-handle to low pulley. Stand with cable passing behind glutes.","Abduct arm out to side smoothly to parallel."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_front_raise', 'Dumbbell Front Raise', 'Isolated shoulder flexion focusing on the anterior deltoid head.', 'dumbbell', 'isolation', 'beginner', '["Hold dumbbells in front of thighs with overhand grip.","Raise one or both dumbbells straight forward to eye level without arching back.","Lower under control."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_front_raise', 'Barbell Front Raise', 'Two-handed bilateral barbell front raise building anterior deltoid density.', 'barbell', 'isolation', 'beginner', '["Hold barbell across thighs. Raise bar forward with straight arms to shoulder height."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_front_raise', 'Cable Front Raise (Rope or Bar)', 'Continuous tension anterior deltoid raise using low pulley cable.', 'cable', 'isolation', 'beginner', '["Straddle low cable with rope attachment between legs. Raise arms forward to eye level."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_face_pull_rope', 'Face Pull (Rope Attachment)', 'Crucial shoulder health movement targeting rear delts, external rotators, and mid traps.', 'cable', 'compound', 'beginner', '["Set cable at upper chest or eye level with rope. Grip rope with thumbs pointing backward.","Step back, pull hands toward eyes/ears while rotating wrists back so knuckles face ceiling.","Squeeze rear delts and mid-traps hard, lower with control."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_rear_delt_dumbbell_fly', 'Rear Delt Dumbbell Fly (Bent-Over)', 'Bent-over lateral raise targeting the posterior deltoids and rhomboids.', 'dumbbell', 'isolation', 'beginner', '["Hinge at hips with torso parallel to floor or seated chest-to-knees.","Raise dumbbells out to sides leading with pinkies and rear delts.","Squeeze posterior shoulders at top, lower smoothly."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_rear_delt_cable_fly', 'Rear Delt Cable Fly (High to Low / Standing)', 'Cross-cable rear delt pull providing smooth resistance across the entire arc.', 'cable', 'isolation', 'beginner', '["Stand between cables without handles, grasping bare carabiners with opposite hands (cross cable).","Pull arms back and outward across chest height squeezing rear delts."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_reverse_pec_deck', 'Machine Reverse Pec Deck (Rear Delt Fly)', 'Guided rear deltoid isolation eliminating body sway and balance requirements.', 'machine', 'isolation', 'beginner', '["Sit chest against pad, handles adjusted all the way back.","Grasp handles with neutral or overhand grip, push arms outward and backward until rear delts fully contract."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_rear_delt_cable_crossover', 'Cable Rear Delt Crossover (Seated Bench)', 'Seated variation isolating rear deltoids with complete upper body stabilization.', 'cable', 'isolation', 'intermediate', '["Sit on upright bench facing cable cross. Pull cables across in horizontal plane."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_upright_row', 'Barbell Upright Row', 'Pulling movement building lateral deltoids and upper trapezius thickness.', 'barbell', 'compound', 'intermediate', '["Grip barbell with hands shoulder-width apart (avoid very narrow grip).","Pull bar up along torso leading with elbows up to chest height.","Lower smoothly under control."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_upright_row', 'Dumbbell Upright Row', 'Allows independent hand freedom to prevent shoulder internal rotation impingement.', 'dumbbell', 'compound', 'beginner', '["Hold dumbbells in front of thighs. Pull elbows high and wide to shoulder level."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_upright_row', 'Cable Upright Row (Rope Attachment)', 'Rope attachment allows hands to separate at peak contraction for maximum side delt recruitment.', 'cable', 'compound', 'beginner', '["Attach rope to low pulley. Pull upward, spreading rope ends apart at collarbone level."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cuban_press', 'Cuban Press (Dumbbell)', 'Combines upright row, external rotation, and overhead press for complete shoulder armor.', 'dumbbell', 'compound', 'advanced', '["Upright row dumbbells to chest height, externally rotate forearms up to 90 degrees, press overhead.","Reverse all three steps under strict control."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lu_raises', 'Lu Raises (Full Range Lateral Raise)', 'Full overhead lateral raise developed by Chinese Olympic weightlifters for shoulder mobility.', 'dumbbell', 'isolation', 'intermediate', '["Start with light dumbbells at sides. Raise arms in a wide arc all the way overhead until dumbbells touch.","Lower along the same arc with control."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_plate_front_raise', 'Plate Front Raise (Steering Wheel)', 'Weight plate raise providing grip strength and isometric rotational challenge to deltoids.', 'barbell', 'isolation', 'beginner', '["Hold weight plate at 9 and 3 o''clock. Raise to eye level and rotate slightly like a steering wheel."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_landmine_shoulder_press', 'Landmine Single-Arm Shoulder Press', 'Angled overhead press sparing the subacromial joint while blasting the front and side delts.', 'barbell', 'compound', 'intermediate', '["Hold tip of landmine barbell at shoulder. Press upward and forward in a natural arc to full extension."]'::jsonb, NULL, NULL, 'shoulders') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_biceps_curl', 'Barbell Biceps Curl', 'The premier mass builder for the biceps brachii using heavy bilateral progressive overload.', 'barbell', 'isolation', 'beginner', '["Stand tall holding barbell with shoulder-width underhand grip, elbows pinned to sides.","Curl the bar upward by flexing elbows while keeping upper arms motionless.","Squeeze biceps hard at top contraction, lower slowly over 2-3 seconds."]'::jsonb, NULL, 'https://www.youtube.com/embed/ykJmrZ5v0Oo', 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_biceps_curl', 'Dumbbell Biceps Curl (Supinating)', 'Allows wrists to rotate from neutral to fully supinated, maximizing biceps recruitment.', 'dumbbell', 'isolation', 'beginner', '["Start with dumbbells at sides, palms facing in.","As you curl upward, rotate wrists so palms face ceiling at peak contraction.","Lower under control reversing the rotation."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_incline_dumbbell_curl', 'Incline Dumbbell Curl', 'Places the long head of the biceps on deep stretch behind the torso for maximum hypertrophy.', 'dumbbell', 'isolation', 'intermediate', '["Sit on bench inclined to 45-60 degrees with arms hanging straight down.","Curl dumbbells upward without letting elbows swing forward.","Lower slowly to full bottom stretch."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_hammer_curl', 'Dumbbell Hammer Curl', 'Neutral grip curl prioritizing the brachialis and brachioradialis for arm thickness.', 'dumbbell', 'isolation', 'beginner', '["Hold dumbbells with palms facing each other (neutral grip).","Curl dumbbells up to shoulder height maintaining thumbs-up position.","Squeeze forearm and outer upper arm at top, lower slowly."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_hammer_curl_rope', 'Cable Hammer Curl (Rope)', 'Continuous cable tension on the brachialis and forearms throughout the entire range.', 'cable', 'isolation', 'beginner', '["Attach rope to low pulley. Hold with neutral grip, elbows tucked at sides.","Curl upward, pulling rope ends slightly outward at top contraction."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_preacher_curl_ez_bar', 'EZ-Bar Preacher Curl', 'Strict bicep isolation eliminating body momentum and targeting the lower biceps stretch.', 'barbell', 'isolation', 'beginner', '["Sit at preacher bench with armpits snug against pad. Hold EZ-bar with inner grip.","Lower bar slowly until arms are nearly fully extended.","Curl bar up to vertical forearm position, squeezing hard."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_preacher_curl_dumbbell', 'Single-Arm Dumbbell Preacher Curl', 'Unilateral preacher curl fixing arm imbalances with pure bicep focus.', 'dumbbell', 'isolation', 'beginner', '["Rest one arm over preacher pad holding dumbbell.","Lower dumbbell under control to full elbow extension, curl up smoothly."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_spider_curl', 'Spider Curl (Chest-Supported Incline)', 'Chest supported on incline bench with arms hanging vertically for extreme peak contraction.', 'barbell', 'isolation', 'intermediate', '["Lie face down on 45-degree incline bench with arms hanging straight down holding EZ-bar.","Curl bar upward without allowing elbows to drift back, focusing on peak bicep squeeze."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_concentration_curl', 'Concentration Curl', 'Classic seated curl bracing elbow against inner thigh to eliminate all cheating.', 'dumbbell', 'isolation', 'beginner', '["Sit on bench, brace tricep against inner thigh.","Curl dumbbell up toward face, supinating wrist at top squeeze."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_biceps_curl', 'Standing Cable Biceps Curl (Straight Bar)', 'Continuous tension cable curl keeping biceps under constant load from start to finish.', 'cable', 'isolation', 'beginner', '["Attach straight bar to low pulley. Stand tall, elbows tucked, curl bar up to chest."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_high_cable_curl_hercules', 'High Cable Curl (Hercules Curl)', 'Dual high pulley bicep curl mimicking front double bicep bodybuilding pose.', 'cable', 'isolation', 'intermediate', '["Stand between high pulleys, arms extended parallel to floor holding stirrup handles.","Curl handles inward toward ears while keeping upper arms horizontal to floor."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_reverse_barbell_curl', 'Reverse Barbell Curl', 'Overhand grip curl targeting the brachioradialis, forearms, and brachialis.', 'barbell', 'isolation', 'beginner', '["Hold barbell with overhand (pronated) grip shoulder-width.","Curl bar up without letting wrists flex back, lower slowly."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_reverse_cable_curl', 'Reverse Cable Curl', 'Overhand cable curl delivering smooth resistance across the forearm and brachialis.', 'cable', 'isolation', 'beginner', '["Attach bar to low pulley with pronated overhand grip. Curl smoothly to upper chest."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_ez_bar_21s_curl', 'EZ-Bar 21s Biceps Curl', 'High-volume fatigue protocol: 7 lower-half reps, 7 upper-half reps, 7 full reps.', 'barbell', 'isolation', 'intermediate', '["Perform 7 reps from bottom to 90 degrees, immediately 7 reps from 90 degrees to top, then 7 full range reps."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_preacher_curl', 'Machine Preacher Curl', 'Pin-loaded preacher curl with cam profile matching human strength curve.', 'machine', 'isolation', 'beginner', '["Sit with chest against pad, grasp handles, curl upward smoothly through guided arc."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_close_grip_barbell_bench_press', 'Close-Grip Barbell Bench Press', 'Heavy compound press shifting maximum mechanical tension onto the triceps brachii.', 'barbell', 'compound', 'intermediate', '["Lie on flat bench. Grip bar with hands shoulder-width apart (not touching to protect wrists).","Lower bar to lower chest while keeping elbows tucked close to ribcage.","Drive upward through triceps lockout."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_triceps_rope_pushdown', 'Triceps Rope Pushdown', 'Cable pushdown allowing flare-out at bottom to recruit the lateral triceps head.', 'cable', 'isolation', 'beginner', '["Attach rope to high pulley. Stand with slight forward torso lean, elbows tucked at sides.","Push rope down and spread ends apart at bottom lockout.","Return slowly to 90 degrees elbow bend."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_straight_bar_triceps_pushdown', 'Straight-Bar Triceps Pushdown', 'Allows heavier loading than rope to build raw triceps pressing power.', 'cable', 'isolation', 'beginner', '["Grip straight bar on high pulley with overhand grip. Push down forcefully to lockout."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_v_bar_triceps_pushdown', 'V-Bar Triceps Pushdown', 'Angled V-bar providing wrist-friendly ergonomics for heavy triceps pushdowns.', 'cable', 'isolation', 'beginner', '["Grip V-bar handle on high cable. Push downward through palms to full elbow extension."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_skull_crushers_lying_triceps_extension', 'Skull Crushers (EZ-Bar Lying Triceps Extension)', 'Classic lying triceps extension isolating the long and medial heads under deep stretch.', 'barbell', 'isolation', 'intermediate', '["Lie flat holding EZ-bar with narrow grip extended over chest.","Hinge at elbows, lowering bar toward forehead or slightly behind crown of head.","Extend elbows back to starting position without letting upper arms swing."]'::jsonb, NULL, 'https://www.youtube.com/embed/d_KZxkY_0cM', 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_overhead_dumbbell_triceps_extension', 'Overhead Dumbbell Triceps Extension (Seated Two-Arm)', 'Places triceps long head on maximum anatomical stretch behind the neck.', 'dumbbell', 'isolation', 'beginner', '["Sit on bench holding one heavy dumbbell vertically overhead with both hands cupping top plate.","Lower weight behind head by flexing elbows, keeping upper arms close to ears.","Press upward back to full overhead extension."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_overhead_cable_triceps_extension', 'Overhead Cable Triceps Extension (Rope)', 'Facing away from cable tower to keep continuous loaded stretch on the long head.', 'cable', 'isolation', 'beginner', '["Set pulley at chest height. Grasp rope, turn away and lean forward into staggered stance.","Extend arms overhead, spreading rope ends apart at full lockout."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_triceps_dips_upright', 'Triceps Dips (Upright Torso)', 'Parallel bar dip with vertical torso and elbows tucked back to target triceps.', 'bodyweight', 'compound', 'intermediate', '["Support body on parallel bars with upright torso and legs straight down.","Lower body by bending elbows backward until arms reach 90 degrees.","Push upward through triceps lockout."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_bench_dips', 'Bench Dips', 'Accessible triceps dip placing hands on bench behind body.', 'bodyweight', 'compound', 'beginner', '["Place hands on edge of bench, feet flat or on opposite bench in front of you.","Lower hips down in front of bench until elbows reach 90 degrees, press up."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_arm_cable_triceps_kickback', 'Single-Arm Cable Triceps Kickback', 'Maintains tension through full shoulder extension without dead spots.', 'cable', 'isolation', 'intermediate', '["Set cable at hip height without handle (hold bare cable). Hinge torso forward.","Keep upper arm parallel to floor, extend forearm back until arm is locked straight."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_triceps_kickback', 'Dumbbell Triceps Kickback', 'Free weight isolation providing peak contraction in full elbow and shoulder extension.', 'dumbbell', 'isolation', 'beginner', '["Brace on bench, upper arm pinned parallel to torso.","Kick dumbbell back until arm is completely straight, pause 1 second."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_jm_press', 'JM Press (Hybrid Bench & Extension)', 'Powerlifting hybrid combining close-grip bench press with triceps extension for immense overload.', 'barbell', 'compound', 'advanced', '["Hold bar over upper chest. Lower bar toward neck/throat by bending elbows and letting them flare slightly forward.","Press up forcefully with pure triceps drive."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_tate_press', 'Tate Press (Dumbbell Triceps Extension)', 'Lying dumbbell extension flaring elbows outward to target the medial and lateral triceps.', 'dumbbell', 'isolation', 'intermediate', '["Lie flat with dumbbells touching over chest, palms facing feet with elbows flared out.","Lower weights inward toward chest by bending elbows, press outward back to top."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_wrist_curl', 'Barbell Wrist Curl (Seated)', 'Forearm flexor builder performed resting forearms across thighs.', 'barbell', 'isolation', 'beginner', '["Sit on bench resting forearms on thighs with wrists hanging off knees, palms facing up.","Lower bar down into fingertips, then curl wrists upward as high as possible."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_reverse_wrist_curl', 'Barbell Reverse Wrist Curl', 'Forearm extensor exercise building top-of-forearm density and wrist durability.', 'barbell', 'isolation', 'beginner', '["Rest forearms on thighs with palms facing down. Curl wrists upward toward ceiling."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_wrist_curl', 'Dumbbell Wrist Curl (Single-Arm)', 'Unilateral wrist curl allowing independent range of motion and wrist flexor focus.', 'dumbbell', 'isolation', 'beginner', '["Rest forearm on bench with wrist over edge, curl dumbbell up and down smoothly."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_farmers_walk', 'Farmer''s Walk (Heavy Carry)', 'Heavy loaded carry building crushing grip, forearm thickness, upper traps, and core stability.', 'dumbbell', 'compound', 'intermediate', '["Deadlift heavy dumbbells or farmer handles. Stand tall with shoulders packed and chest up.","Walk forward with smooth, controlled steps for distance or time, fighting any torso sway."]'::jsonb, NULL, NULL, 'arms') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_back_squat_high_bar', 'Barbell Back Squat (High Bar)', 'The king of quad builders, demanding knee flexion and deep ankle mobility with bar on traps.', 'barbell', 'compound', 'intermediate', '["Rest barbell high across upper trapezius. Stand with feet slightly wider than shoulder-width, toes turned 15-30 degrees.","Inhale deep into abdomen, break at hips and knees simultaneously.","Descend until hip crease is below top of knees, keeping chest proud and knees tracking over toes.","Drive powerfully out of the hole through mid-foot."]'::jsonb, NULL, 'https://www.youtube.com/embed/bEv6CCg2BC8', 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_back_squat_low_bar', 'Barbell Back Squat (Low Bar)', 'Powerlifting squat style resting bar across rear delts to recruit maximum posterior chain power.', 'barbell', 'compound', 'advanced', '["Rest bar across rear delts/scapular spine. Lean torso forward slightly more than high bar.","Sit back into hips, descend to parallel, drive up leading with hips."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_front_squat_barbell', 'Barbell Front Squat', 'Bar resting on anterior deltoids forcing an upright torso and extreme quadriceps focus.', 'barbell', 'compound', 'advanced', '["Rest bar across clavicles and front delts in clean grip or cross-arm grip with elbows driven high.","Descend straight down between knees keeping torso vertical.","Drive out of hole without dropping elbows."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_zercher_squat', 'Zercher Squat (Bar in Crooks of Elbows)', 'Bar cradled in the crooks of elbows, building unbreakable core strength and quad drive.', 'barbell', 'compound', 'advanced', '["Cradle barbell in crooks of elbows against chest with hands clasped.","Squat deep between knees keeping upright posture, drive up forcefully."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_safety_bar_squat', 'Safety Bar Squat (SSB)', 'Yoke bar sparing shoulders and wrists while maintaining upright quad-heavy mechanics.', 'barbell', 'compound', 'intermediate', '["Grip handles of Safety Squat Bar resting on shoulders.","Squat under control, resisting bar''s tendency to pitch torso forward."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hack_squat_machine', 'Hack Squat (Machine)', 'Supported back sled eliminating spinal balance, allowing complete quadriceps failure safely.', 'machine', 'compound', 'beginner', '["Position back flat against pad, shoulders under shoulder pads. Feet shoulder-width on platform.","Release safety handles, descend until knees achieve deep flexion (below 90 degrees).","Press platform away driving through mid-foot."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_leg_press_45_degree', '45-Degree Leg Press', 'Heavy plate-loaded leg press allowing immense quadriceps and glute loading with fixed spine.', 'machine', 'compound', 'beginner', '["Sit firmly in seat with lower back pinned against pad. Place feet shoulder-width on sled.","Lower sled until knees reach 90 degrees without rounding lower back off pad.","Press sled back up without hyperextending or locking knees."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_walking_lunge', 'Dumbbell Walking Lunge', 'Dynamic unilateral leg builder testing single-leg strength, balance, and glute-quad coordination.', 'dumbbell', 'compound', 'intermediate', '["Hold dumbbells at sides. Step forward into lunge, lowering back knee until hovering above floor.","Drive through front heel to step directly forward into next lunge stride."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_reverse_lunge_dumbbell', 'Dumbbell Reverse Lunge', 'Knee-friendly lunge variation stepping backward to preserve patellar tendon comfort.', 'dumbbell', 'compound', 'beginner', '["Step backward with one leg, lower hips until front thigh is parallel to floor.","Drive through front heel to return to standing."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_bulgarian_split_squat', 'Bulgarian Split Squat (Rear-Foot Elevated)', 'The premier single-leg exercise placing devastating hypertrophy stimulus on quads and glutes.', 'dumbbell', 'compound', 'intermediate', '["Rest laces of back foot on bench behind you. Front foot planted 2-3 feet in front.","Descend until back knee nearly touches floor, front knee bent 90 degrees.","Drive up through front heel to return to top."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_goblet_squat', 'Goblet Squat (Dumbbell or Kettlebell)', 'Accessible squat teaching perfect upright posture and deep hip mobility.', 'dumbbell', 'compound', 'beginner', '["Hold dumbbell vertically against chest with elbows pointing down.","Squat deep between knees, pushing knees out, drive up through heels."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_sissy_squat_bodyweight', 'Sissy Squat (Bodyweight / Bench)', 'Extreme knee flexion isolation movement providing loaded stretch across the rectus femoris.', 'bodyweight', 'isolation', 'advanced', '["Lock shins into sissy squat bench or hold sturdy post.","Lean torso back while driving knees forward to achieve complete quad stretch, press up."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_leg_extension_machine', 'Leg Extension (Machine)', 'Open-chain knee extension isolating the rectus femoris and vastus muscles in peak contraction.', 'machine', 'isolation', 'beginner', '["Adjust back pad so knees align with machine pivot. Pad resting on lower shins.","Extend knees until legs are straight, squeezing quads hard for 1 second at top.","Lower weight under control to 90 degrees."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_romanian_deadlift_barbell', 'Barbell Romanian Deadlift (RDL)', 'Gold standard posterior chain builder focusing on loaded eccentric stretch of the hamstrings.', 'barbell', 'compound', 'intermediate', '["Stand tall holding barbell with overhand grip, knees slightly unlocked (soft).","Push hips backward as far as possible while keeping bar brushing down thighs.","Lower until deep stretch is felt in hamstrings (mid-shin level), keeping back flat.","Drive hips forward to return to standing."]'::jsonb, NULL, 'https://www.youtube.com/embed/2SHsk9AzdjA', 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_romanian_deadlift_dumbbell', 'Dumbbell Romanian Deadlift', 'Dumbbell variation allowing dumbbells to track beside legs for lower back comfort.', 'dumbbell', 'compound', 'beginner', '["Hold dumbbells in front of thighs, hinge hips back until deep hamstring stretch, drive forward."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_stiff_legged_deadlift', 'Stiff-Legged Deadlift (From Floor)', 'Starting from the floor with higher hips to maximize hamstring and lower back range.', 'barbell', 'compound', 'advanced', '["Set up with knees almost straight, hips elevated high. Pull bar off floor using pure posterior chain."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lying_leg_curl_machine', 'Lying Leg Curl (Machine)', 'Isolates the knee flexion function of the hamstrings across both heads.', 'machine', 'isolation', 'beginner', '["Lie face down on machine with pad against lower calves/Achilles tendon.","Curl heels toward glutes without lifting hips off pad.","Hold peak squeeze for 1 second, lower smoothly over 3 seconds."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_leg_curl_machine', 'Seated Leg Curl (Machine)', 'Places hip in 90 degrees flexion, lengthening hamstrings for superior muscle hypertrophy.', 'machine', 'isolation', 'beginner', '["Sit firmly with thigh pad locked down tight. Pad resting on lower calves.","Curl heels down and back under seat to full contraction.","Control the eccentric return feeling deep hamstring stretch."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_standing_single_leg_curl', 'Standing Single-Leg Curl', 'Unilateral machine curl evening out hamstring strength disparities between limbs.', 'machine', 'isolation', 'beginner', '["Brace torso against pad, curl single heel up toward glute with smooth squeeze."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_nordic_hamstring_curl', 'Nordic Hamstring Curl', 'Bodyweight eccentric powerhouse proven to maximize hamstring hypertrophy and injury prevention.', 'bodyweight', 'compound', 'advanced', '["Kneel on pad with ankles anchored firmly behind you. Keep hips fully extended in a line.","Slowly lower body forward toward floor, resisting gravity purely with hamstrings.","Catch yourself with hands on floor, push lightly back up."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_glute_ham_raise_ghr', 'Glute-Ham Raise (GHR)', 'Integrates both knee flexion and hip extension functions of the posterior chain simultaneously.', 'machine', 'compound', 'advanced', '["Mount GHR bench with feet locked between rollers and knees on curved pad.","Lower torso forward to horizontal, then bend knees pulling body back upright."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_step_up_dumbbell', 'Dumbbell Step-Up', 'Functional single-leg drive onto box building unilateral quad power and glute drive.', 'dumbbell', 'compound', 'beginner', '["Hold dumbbells at sides facing sturdy box or bench.","Place entire foot on box, drive through heel to stand tall on top without bouncing off trailing foot.","Lower back down under control."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_box_squat_barbell', 'Barbell Box Squat', 'Squatting to a box breaks the stretch-shortening cycle to build explosive hip drive.', 'barbell', 'compound', 'intermediate', '["Squat back until sitting gently on box without rocking. Pause, explode upward through heels."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_standing_calf_raise_machine', 'Standing Calf Raise (Machine)', 'Full knee extension calf raise maximizing tension on the gastrocnemius.', 'machine', 'isolation', 'beginner', '["Place balls of feet on block, shoulders under pads, knees locked straight.","Lower heels into deep calf stretch, explode upward onto big toes.","Hold peak calf contraction for 2 seconds before descending."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_calf_raise_machine', 'Seated Calf Raise (Machine)', 'Bent knee position slacks the gastrocnemius, isolating the deep soleus muscle.', 'machine', 'isolation', 'beginner', '["Sit with knees under pad bent at 90 degrees. Balls of feet on block.","Lower heels to full ankle stretch, drive upward onto toes, pause."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_leg_press_calf_raise', 'Leg Press Calf Raise (Toe Press)', 'Straight-leg calf extension on leg press sled allowing heavy, safe progressive overload.', 'machine', 'isolation', 'beginner', '["Place balls of feet on lower edge of leg press platform with heels hanging free.","Press sled forward through ankle extension, lower under deep stretch."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_donkey_calf_raise', 'Donkey Calf Raise', 'Bent-over hip angle prestretches the hamstrings and gastrocnemius for peak calf activation.', 'machine', 'isolation', 'intermediate', '["Bend forward at hips resting weight pad across sacrum. Raise heels high, lower to stretch."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_leg_dumbbell_calf_raise', 'Single-Leg Dumbbell Calf Raise', 'Unilateral standing calf raise fixing left-to-right ankle strength imbalances.', 'dumbbell', 'isolation', 'beginner', '["Stand on one foot on step holding dumbbell in same-side hand.","Drop heel into deep stretch, drive up high on big toe."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_tibialis_anterior_raise_wall', 'Tibialis Anterior Raise (Wall Lean)', 'Crucial shin muscle strengthener protecting knees and improving ankle dorsiflexion.', 'bodyweight', 'isolation', 'beginner', '["Lean upper back against wall with legs extended in front.","Flex toes upward toward shins as high as possible, hold 1 second, lower slowly."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_tibialis_anterior_cable_pull', 'Tibialis Anterior Cable Pull', 'Weighted ankle dorsiflexion using ankle strap and low pulley cable.', 'cable', 'isolation', 'intermediate', '["Sit on bench facing low pulley with strap attached around forefoot.","Pull toes back toward knee against cable resistance."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_smith_machine_squat', 'Smith Machine Squat (Feet Forward)', 'Placing feet forward reduces lower back shear and places massive focus on the quads.', 'smith_machine', 'compound', 'beginner', '["Step feet 12-18 inches in front of bar. Descend deep into upright quad squat, press up."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_smith_machine_calf_raise', 'Smith Machine Standing Calf Raise', 'Allows heavy standing calf training on wooden block with built-in safety catches.', 'smith_machine', 'isolation', 'beginner', '["Place calf block under bar. Unhook bar on upper traps, raise heels high onto toes."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_deficit_romanian_deadlift', 'Deficit Romanian Deadlift (Standing on Plate)', 'Standing on 2-inch plate for extreme hamstring loaded stretch at bottom of hinge.', 'barbell', 'compound', 'advanced', '["Stand on 2-inch platform or bumper plate. Hinge deeply past toe level feeling intense hamstring stretch."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_overhead_squat_barbell', 'Overhead Squat (Barbell)', 'Olympic lifting test of full-body mobility, balance, thoracic extension, and leg drive.', 'barbell', 'compound', 'advanced', '["Snatch or press bar wide overhead. Squat deep keeping bar directly over mid-foot with locked elbows."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_good_morning_safety_bar', 'Safety Bar Good Morning', 'Hinge exercise with SSB bar targeting the hamstrings and spinal erectors comfortably.', 'barbell', 'compound', 'intermediate', '["Hinge hips backward with soft knees, feeling deep hamstring stretch before driving upright."]'::jsonb, NULL, NULL, 'legs') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_barbell_hip_thrust', 'Barbell Hip Thrust', 'The premier glute hypertrophy exercise delivering peak horizontal tension at full hip extension.', 'barbell', 'compound', 'intermediate', '["Sit on floor with upper back against bench, loaded barbell over hips (with thick pad).","Plant feet hip-width with shins vertical at top of movement.","Drive through heels, extending hips until thighs and torso form a straight horizontal line.","Posteriorly tilt pelvis and squeeze glutes hard at top for 1-2 seconds, lower slowly."]'::jsonb, NULL, 'https://www.youtube.com/embed/SEdqd1n0cvg', 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_single_leg_hip_thrust', 'Single-Leg Hip Thrust (Bodyweight or Dumbbell)', 'Unilateral hip thrust eliminating glute strength discrepancies and challenging pelvic stability.', 'dumbbell', 'compound', 'intermediate', '["Upper back on bench, lift one foot off floor with 90-degree knee bend.","Drive working heel into floor to raise hips to full extension, squeeze glute at top."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_kas_glute_bridge', 'Kas Glute Bridge (Slow Tempo / Upper Range)', 'Targeted glute movement using a smaller range of motion to keep tension strictly on the glute max.', 'barbell', 'isolation', 'intermediate', '["Position back on bench as in hip thrust. Move purely at the hip joint without bending knees forward.","Descend only halfway, drive up and squeeze glutes for 2 seconds at peak."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_glute_bridge', 'Dumbbell Glute Bridge (Floor)', 'Floor-based glute bridge with dumbbell resting across pelvis, friendly for all fitness levels.', 'dumbbell', 'isolation', 'beginner', '["Lie flat on back with knees bent, feet flat on floor. Hold dumbbell over hips.","Drive heels down to bridge hips upward until straight line from knees to shoulders."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_glute_kickback', 'Cable Glute Kickback (Straight Leg or Bent)', 'Isolated hip extension using ankle cuff to deliver peak glute contraction.', 'cable', 'isolation', 'beginner', '["Attach ankle strap to low cable. Face machine, hinge slightly at hips holding pole.","Kick working leg straight backward, squeezing glute at top without arching lower back."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_machine_glute_kickback', 'Machine Glute Kickback', 'Guided track plate or pin-loaded kickback isolating glutes with fixed torso support.', 'machine', 'isolation', 'beginner', '["Place working foot on footplate, chest against pad. Drive leg backward and upward."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hyperextension_glute_focus', '45-Degree Hyperextension (Glute Biased)', 'Feet flared 45 degrees and spine rounded to turn back extension into a pure glute builder.', 'bodyweight', 'isolation', 'beginner', '["Set pad below hip crease. Turn toes out 45 degrees, round upper back (slight hunch).","Hinge forward, then extend hips by driving hips into pad and squeezing glutes tightly."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_pull_through', 'Cable Pull-Through', 'Teaches powerful hip hinge mechanics with horizontal cable resistance loading the glutes.', 'cable', 'compound', 'beginner', '["Attach rope to low pulley. Face away from cable with rope between legs.","Hinge hips back feeling glute/hamstring stretch, snap hips forward to standing lockout."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_frog_pumps', 'Frog Pumps (Glute Burnout)', 'Soles of feet together in butterfly position, removing hamstring involvement for glutes.', 'bodyweight', 'isolation', 'beginner', '["Lie on floor with soles of feet pressed together and knees flared wide.","Bridge hips up rapidly, squeezing glutes tightly at top for high repetitions."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_curtsy_lunge', 'Curtsy Lunge (Dumbbell)', 'Crossing leg behind torso to place deep loaded stretch on the gluteus medius and maximus.', 'dumbbell', 'compound', 'intermediate', '["Step one leg back and across behind front leg as if curtsying.","Lower hips until front thigh is parallel, push through front heel to stand."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_b_stance_romanian_deadlift', 'B-Stance Romanian Deadlift (Kickstand RDL)', 'Kickstand single-leg RDL offering stability of two legs with unilateral glute bias.', 'dumbbell', 'compound', 'intermediate', '["Front foot flat, back foot resting on toes 10 inches behind for kickstand balance.","Hinge hips back loaded onto front glute, drive hip forward to stand."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_step_up_glute_biased', 'Glute-Biased Step-Up (Slow Eccentric)', 'Leaning torso forward over working thigh on box to maximize glute hip extension.', 'dumbbell', 'compound', 'intermediate', '["Place foot on box at knee height. Lean torso forward over thigh.","Drive straight up through heel without pushing off trailing toes, lower slowly over 3 seconds."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lateral_band_walk', 'Lateral Band Walk (Monster Walk)', 'Resistance band around ankles or knees activating the gluteus medius and hip abductors.', 'band', 'isolation', 'beginner', '["Loop mini-band around ankles, soften knees into quarter squat.","Step laterally keeping toes forward and tension continuously on band."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_clamshell_banded', 'Banded Clamshell', 'Sidelying hip external rotation isolating the gluteus medius and deep hip rotators.', 'band', 'isolation', 'beginner', '["Lie on side with hips and knees at 45 degrees, band around knees, feet touching.","Open top knee toward ceiling without rolling hips backward."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_hip_abduction', 'Cable Hip Abduction (Standing)', 'Ankle cuff cable abduction building the upper shelf of the gluteus medius.', 'cable', 'isolation', 'beginner', '["Attach cuff to ankle on far leg. Abduct leg out to side against cable resistance."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_machine_hip_abduction', 'Seated Machine Hip Abduction', 'Strict machine abductor exercise targeting the gluteus medius, minimus, and upper max.', 'machine', 'isolation', 'beginner', '["Sit back in machine with pads against outer knees.","Push knees outward as wide as possible, pause for 1 second, control return."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_standing_cable_kickback_angled', '45-Degree Angled Cable Glute Kickback', 'Combines hip extension with slight abduction to recruit both gluteus maximus and medius.', 'cable', 'isolation', 'intermediate', '["Kick leg back at a 45-degree angle outward from body, squeezing upper outer glute."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_sumo_squat_glutes', 'Dumbbell Sumo Squat (Glute Focus)', 'Wide stance squat with dumbbell held between legs targeting glutes and inner thighs.', 'dumbbell', 'compound', 'beginner', '["Stand with wide stance, toes turned out 45 degrees holding dumbbell hanging vertically.","Squat down opening knees wide, drive through heels squeezing glutes at top."]'::jsonb, NULL, NULL, 'glutes') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_hanging_leg_raise', 'Hanging Leg Raise', 'Gold standard lower abdominal exercise flexing pelvis toward ribcage from a dead hang.', 'bodyweight', 'compound', 'advanced', '["Hang from pull-up bar with overhand grip, legs straight.","Posteriorly tilt pelvis and raise straight legs up until parallel to floor or touching bar.","Control the descent slowly without swinging."]'::jsonb, NULL, 'https://www.youtube.com/embed/hdng3Nm1x_E', 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_captains_chair_knee_raise', 'Captain''s Chair Knee Raise', 'Supported forearm knee raise targeting rectus abdominis with zero lower back strain.', 'bodyweight', 'isolation', 'beginner', '["Support body on forearm pads of tower, back against pad.","Curl knees up toward chest, curling pelvis upward at peak."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_ab_wheel_rollout', 'Ab Wheel Rollout', 'Extreme anti-extension core exercise building bulletproof abdominal wall strength.', 'bodyweight', 'compound', 'advanced', '["Kneel on pad holding ab wheel beneath shoulders with slightly rounded upper back.","Roll wheel forward extending body as far as possible without letting lumbar spine sag.","Pull back by flexing abdominals to return to start."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_woodchopper', 'Cable Woodchopper (High to Low / Diagonal)', 'Rotational power exercise building functional oblique and transverse abdominal strength.', 'cable', 'compound', 'intermediate', '["Stand sideways to high cable holding handle with both hands extended.","Rotate torso diagonally downward across body toward opposite hip, pivoting back foot.","Control cable return with core."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_crunch', 'Cable Kneeling Crunch (Rope)', 'Allows progressive overload on the rectus abdominis with constant cable tension.', 'cable', 'isolation', 'beginner', '["Kneel below high pulley holding rope at temples. Keep hips fixed in place.","Curl torso downward curling ribcage toward pelvis, exhaling fully at bottom.","Allow cable to stretch abs back to start without sitting back on heels."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_decline_sit_up', 'Decline Bench Sit-Up', 'Extended range sit-up targeting the upper and mid rectus abdominis.', 'bodyweight', 'compound', 'intermediate', '["Hook feet in decline bench, cross arms over chest.","Lower torso until hovering above bench, curl spine up to seated."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_elbow_plank', 'Elbow Plank (Front Plank)', 'Fundamental isometric anti-extension core hold building endurance and pelvic control.', 'bodyweight', 'isolation', 'beginner', '["Rest on forearms and toes with elbows under shoulders.","Squeeze glutes, tuck pelvis, pull belly button inward, hold completely motionless."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_side_plank', 'Side Plank', 'Isometric anti-lateral flexion hold strengthening the obliques and quadratus lumborum.', 'bodyweight', 'isolation', 'beginner', '["Lie on side propped on elbow. Lift hips creating a straight diagonal line from head to feet.","Hold position without letting bottom hip sag toward floor."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_russian_twists', 'Russian Twists (Weighted / Bodyweight)', 'Rotational core movement challenging obliques and hip flexor coordination.', 'dumbbell', 'isolation', 'beginner', '["Sit with knees bent, feet elevated off floor, torso leaned back 45 degrees.","Rotate torso side to side, tapping weight on floor beside hips."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dragon_flag', 'Dragon Flag (Bruce Lee Ab Movement)', 'Legendary advanced core test keeping the entire body rigid while hinging off the upper back.', 'bodyweight', 'compound', 'advanced', '["Lie on bench gripping edge behind head. Drive legs and torso straight up to vertical.","Lower straight body slowly in one line until hovering above bench, then pull back up."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_toes_to_bar', 'Toes-to-Bar (Hanging)', 'Full range gymnastics abdominal pull bringing toes all the way to contact the pull-up bar.', 'bodyweight', 'compound', 'advanced', '["Hang from bar. Initiate by flexing lats, curl hips and legs up until toes touch the bar."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_pallof_press', 'Pallof Press (Anti-Rotation)', 'Pure anti-rotation core trainer building athletic rotational resistance.', 'cable', 'isolation', 'beginner', '["Stand perpendicular to cable tower holding handle at sternum with both hands.","Press hands straight out in front of chest, fighting cable''s rotational pull.","Hold 2 seconds with arms locked, return to chest."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_mountain_climbers', 'Mountain Climbers (Dynamic Plank)', 'High tempo plank variation driving knees to chest for dynamic core and hip endurance.', 'bodyweight', 'compound', 'beginner', '["In high push-up plank, drive alternate knees toward chest rapidly while keeping hips level."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dead_bug', 'Dead Bug (Contralateral Limb Reach)', 'Rehabilitation and athletic staple teaching lumbar stabilization with contralateral limb movement.', 'bodyweight', 'isolation', 'beginner', '["Lie on back with knees bent 90 degrees and arms pointing to ceiling. Press lower back flat into floor.","Simultaneously lower right arm overhead and left leg toward floor without arching lower back.","Return to center and switch sides."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_bird_dog', 'Bird Dog (Quadruped Reach)', 'McGill Big 3 movement building spinal stability and posterior chain connection.', 'bodyweight', 'isolation', 'beginner', '["On hands and knees, reach opposite arm forward and leg backward in line with spine. Hold 2 seconds."]'::jsonb, NULL, NULL, 'core') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_seated_machine_hip_adduction', 'Seated Machine Hip Adduction', 'Strict machine adductor movement squeezing legs inward against resistance.', 'machine', 'isolation', 'beginner', '["Sit in machine with legs open wide, pads on inner knees/thighs.","Squeeze knees inward together smoothly, hold contraction for 1-2 seconds at center.","Return slowly feeling loaded adductor stretch."]'::jsonb, NULL, 'https://www.youtube.com/embed/s32e3h2pL9I', 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_standing_cable_hip_adduction', 'Standing Cable Hip Adduction', 'Ankle cuff cable adduction pulling leg across the centerline of the body.', 'cable', 'isolation', 'beginner', '["Attach ankle cuff to near-side leg. Stand perpendicular to low pulley.","Pull working leg across front of standing leg, squeezing inner thigh."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_copenhagen_plank', 'Copenhagen Plank (Adductor Side Plank)', 'Elite adductor strengthening exercise proven in sports science to prevent groin strains.', 'bodyweight', 'compound', 'advanced', '["Place top foot on bench, bottom leg hanging beneath. Prop body up on elbow in side plank.","Hold position supporting body mass through top inner thigh and oblique."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_sumo_deadlift_adductor_bias', 'Sumo Deadlift (Adductor Biased)', 'Ultra-wide stance deadlift maximizing mechanical tension on the adductor magnus.', 'barbell', 'compound', 'advanced', '["Take an ultra-wide stance with shins vertical against bar. Drive knees wide outward.","Push floor apart through heels, driving adductors and glutes to lockout."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_wide_stance_leg_press', 'Wide-Stance Leg Press (Feet High & Wide)', 'Feet placed high and wide on platform to recruit the adductors and deep glutes.', 'machine', 'compound', 'beginner', '["Place feet at top outer corners of sled with toes turned 45 degrees outward.","Lower sled deep, keeping knees tracking over toes, press back up."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cossack_squat', 'Cossack Squat (Lateral Squat)', 'Full depth lateral squat loaded on one leg while putting trailing leg adductors on deep stretch.', 'bodyweight', 'compound', 'intermediate', '["Stand with wide feet. Squat down to one side, keeping other leg straight with toes rotated up.","Achieve deep hip flexion, push through heel to return to center."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_lateral_lunge_dumbbell', 'Dumbbell Lateral Lunge (Side Lunge)', 'Dynamic frontal plane movement building adductor deceleration and lateral hip strength.', 'dumbbell', 'compound', 'beginner', '["Step wide to the side, sinking hips back into lunge while keeping trailing leg straight.","Push off working foot to return to standing."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_cable_adductor_kick_in', 'Cable Adductor Kick-In (Low Pulley)', 'Constant tension inner thigh pull crossing leg inward past midline.', 'cable', 'isolation', 'beginner', '["Cuff on ankle, pull leg inward across body with straight knee, pause 1 second."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_adductor_squeeze_ball', 'Isometric Adductor Squeeze (Medicine Ball or Yoga Block)', 'Isometric adductor hold building tendon strength and pelvic stability.', 'bodyweight', 'isolation', 'beginner', '["Lie on back with knees bent. Place medicine ball or foam block between knees.","Squeeze knees together as hard as possible for 10-15 seconds per rep."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.exercises (id, name, description, equipment, movement_type, difficulty, instructions, image_url, video_url, target_region_id) VALUES ('ex_dumbbell_goblet_sumo_squat', 'Dumbbell Goblet Sumo Squat', 'Upright goblet hold allowing deep adductor stretch and safe knee tracking.', 'dumbbell', 'compound', 'beginner', '["Hold dumbbell at chest with wide stance, toes turned out.","Squat deep between knees, pushing knees out against adductors, drive up."]'::jsonb, NULL, NULL, 'inner_thigh') ON CONFLICT (id) DO NOTHING;
